import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot(timeout=5);s=r.spec();cams=['top','side','oblique']
def measure(o):
 out={}
 for cam in cams:
  arr=np.asarray(o.depth[cam]); print('shape',cam,arr.shape)
  d=arr[-1] if arr.ndim==3 else np.squeeze(arr);im=o.last[cam];K=np.array(o.meta['cameras'][cam]['intrinsic_cv']);T=np.array(o.meta['cameras'][cam]['cam2world_gl']);v,u=np.indices(d.shape);xyz=np.stack([(u-160)/230.5179*d,-(v-120)/230.5179*d,-d,np.ones_like(d)],-1)@T.T;lum=im.astype(float).mean(2)
  m=(xyz[:,:,0]>-.10)&(xyz[:,:,0]<.15)&(xyz[:,:,1]>-.10)&(xyz[:,:,1]<.17)&(xyz[:,:,2]>.70)&(xyz[:,:,2]<.78)&(lum>220)&(d<1.2);p=xyz[m,:3];out[cam]=[len(p),p.mean(0).round(4).tolist() if len(p) else None]
 return out
o=r.get_obs(cameras=cams,include_depth=True,video='both'); target=np.array(o.meta['proprio']['now'][58:87],float);print('before',measure(o));q=target.copy();q[3]+=.02
try:
 res=r.submit('joint_position',q,dt=.35,cameras=cams,video='both',include_depth=True,note='small joint 4 probe');print('probe',measure(res))
 for cam,im in res.last.items():
  import PIL.Image;PIL.Image.fromarray(im).save('/app/output/probe2_'+cam+'.png')
finally:
 rr=r.submit('joint_position',target,dt=.35,cameras=cams,video='both',note='return probe');print('returned',rr.meta.get('done'))
